"""
通用 TCP 服务端模块
基于 QThread 实现，支持多 DCC（Maya、3ds Max、Substance Painter 等）
通过 Qt Signal 将代码执行请求投递到主线程
"""

from __future__ import annotations

import socket
import threading
import sys
import io
import json
import traceback
from typing import Any, Dict, Optional, Callable

try:
    from PySide2.QtGui import QIcon
    from PySide2.QtWidgets import QToolButton
    from PySide2.QtCore import QThread, Signal, QObject
except ImportError:
    from PySide6.QtGui import QIcon
    from PySide6.QtWidgets import QToolButton
    from PySide6.QtCore import QThread, Signal, QObject

from .protocol import Request, Response, encode_message, decode_message


class RequestHandler(QObject):
    """
    请求处理器（运行在主线程）
    
    通过 Signal 接收来自 SocketServerThread 的请求，
    在主线程中执行代码并返回结果。
    """
    
    execute_request = Signal(object, dict, object)
    """Signal: (connection_object, request_dict, done_event)"""
    
    def __init__(self, adapter):
        super().__init__()
        self.adapter = adapter
        self.logger = adapter.get_logger()
        self.execute_request.connect(self._handle_request)
    
    def _handle_request(self, conn, request_data: dict, done_event):
        try:
            request = Request.from_dict(request_data)
        except Exception as e:
            self.logger.error(f"Failed to parse request: {e}")
            try:
                response = Response.failure(id="unknown", message=f"Invalid request: {e}")
                conn.send(encode_message(response))
            except:
                pass
            finally:
                done_event.set()
            return
        
        try:
            response = self._process_request(request)
        except Exception as e:
            self.logger.error(f"Error processing request: {e}")
            self.logger.error(traceback.format_exc())
            response = Response.failure(id=request.id, message=str(e), traceback=traceback.format_exc())
        
        try:
            conn.send(encode_message(response))
        except Exception as e:
            self.logger.error(f"Failed to send response: {e}")
        finally:
            done_event.set()
    
    def _process_request(self, request: Request) -> Response:
        method = request.method
        params = request.params
        
        old_stdout = sys.stdout
        old_stderr = sys.stderr
        captured = io.StringIO()
        sys.stdout = captured
        sys.stderr = captured
        
        try:
            if method == "execute":
                exec_file = params.get("exec_file")
                exec_origin = params.get("exec_origin", "")
                name_var = params.get("name_var", "__main__")
                is_debugging = params.get("is_debugging", False)
                
                # 调试模式下恢复真实 stdout/stderr，让 debugpy 捕获 print 输出
                # 并发送到 VS Code 的调试控制台（DEBUG CONSOLE）
                if is_debugging:
                    sys.stdout = old_stdout
                    sys.stderr = old_stderr
                
                from .execute import main
                main(exec_file=exec_file, exec_origin=exec_origin,
                     name_var=name_var, is_debugging=is_debugging)
                
            elif method == "reload":
                workspace_folders = params.get("workspace_folders", [])
                from .reload import reload
                reload(workspace_folders)
                
            elif method == "start_debugpy":
                # 临时恢复 stdout/stderr，让所有日志和 debugpy 的调试信息能实时输出到控制台
                sys.stdout = old_stdout
                sys.stderr = old_stderr
                try:
                    port = params.get("port", 7012)
                    python_path = params.get("python_path") or self.adapter.get_python_path()
                    self.logger.info(f"[DEBUG] Handling start_debugpy: port={port}, python_path={python_path}")
                    try:
                        from .debug import start_debugpy_server
                        self.logger.info(f"[DEBUG] import start_debugpy_server succeeded")
                    except Exception as import_err:
                        self.logger.error(f"[ERROR] Failed to import start_debugpy_server: {import_err}")
                        self.logger.error(traceback.format_exc())
                        raise
                    result = start_debugpy_server(port, python_path)
                    self.logger.info(f"[DEBUG] start_debugpy_server returned: {result}")
                    
                    debug_logs = [
                        f"[DEBUG] Handling start_debugpy: port={port}, python_path={python_path}",
                        f"[DEBUG] start_debugpy_server returned: {result}"
                    ]
                    return Response.success(id=request.id, output=debug_logs)
                finally:
                    # 恢复捕获状态
                    sys.stdout = captured
                    sys.stderr = captured
                
            elif method == "install_debugpy":
                # 不恢复 stdout/stderr，让 pip 安装日志通过 captured 返回给
                # VS Code 的 DCC Python 输出频道，而非直接输出到 DCC 控制台
                python_path = params.get("python_path") or self.adapter.get_python_path()
                self.logger.info(f"[DEBUG] Handling install_debugpy: python_path={python_path}")
                from .debug import install_debugpy
                install_debugpy(python_path)
                
            elif method == "eval_function":
                module_name = params.get("module")
                func_name = params.get("function")
                kwargs = params.get("kwargs", {})
                
                if not module_name or not func_name:
                    return Response.failure(id=request.id, message="Missing module or function name")
                
                module = __import__(module_name, fromlist=[func_name])
                func = getattr(module, func_name)
                func(**kwargs)
                
            elif method == "add_sys_path":
                path = params.get("path", "")
                self.adapter.add_sys_path(path)
                
            else:
                return Response.failure(id=request.id, message=f"Unknown method: {method}")
            
            output = captured.getvalue().strip()
            output_lines = output.split("\n") if output else []
            
            return Response.success(id=request.id, output=output_lines)
            
        except Exception as e:
            error_detail = traceback.format_exc()
            self.logger.error(f"Execution failed: {e}")
            self.logger.error(f"Error detail: {error_detail}")
            return Response.failure(id=request.id, message=str(e), traceback=error_detail)
            
        finally:
            sys.stdout = old_stdout
            sys.stderr = old_stderr


class SocketServerThread(QThread):
    """
    Socket 服务线程（运行在后台）
    
    监听指定端口，接收客户端连接，解析请求并通过 Signal 投递到主线程。
    """
    
    log_signal = Signal(str)
    """Signal: 日志消息"""
    
    def __init__(self, port: int = 7002, adapter=None):
        super().__init__()
        self.port = port
        self.adapter = adapter
        self.logger = adapter.get_logger() if adapter else None
        self.server_socket = None
        self.running = True
        
        self.request_handler = RequestHandler(adapter)
    
    def run(self):
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind(('127.0.0.1', self.port))
            self.server_socket.listen(5)
            self.server_socket.settimeout(1.0)
            
            self._log(f"Server started, listening on 127.0.0.1:{self.port}")
            self._log("Waiting for connections...")
            
            while self.running:
                try:
                    conn, addr = self.server_socket.accept()
                    self._log(f"Client connected: {addr}")
                    threading.Thread(
                        target=self._handle_client,
                        args=(conn, addr),
                        daemon=True
                    ).start()
                except socket.timeout:
                    continue
                except Exception as e:
                    if self.running:
                        self._log(f"Error accepting connection: {e}")
                        
        except Exception as e:
            self._log(f"Failed to start server: {e}")
        finally:
            self._cleanup()
            self._log("Server stopped")
    
    def _handle_client(self, conn, addr):
        try:
            # 长连接模式：较长超时，支持多次请求
            conn.settimeout(300.0)
            buffer = b""
            self._log(f"Client {addr} connected (persistent mode)")
            
            while self.running:
                try:
                    data = conn.recv(4096)
                    if not data:
                        # 客户端主动断开
                        break
                    buffer += data
                    
                    # 尝试从缓冲区解析所有完整消息
                    while True:
                        message = decode_message(buffer)
                        if message is None:
                            break
                        
                        msg_length = 4 + len(json.dumps(message.to_dict(), ensure_ascii=False).encode('utf-8'))
                        buffer = buffer[msg_length:]
                        
                        if isinstance(message, Request):
                            # self._log(f"Received request: {message.method}\n")
                            # 等待主线程处理完成，但不关闭连接
                            done_event = threading.Event()
                            self.request_handler.execute_request.emit(conn, message.to_dict(), done_event)
                            done_event.wait(timeout=60.0)
                        else:
                            self._log("Received non-request message, ignoring")
                            
                except socket.timeout:
                    # 长连接超时，检查是否仍在运行
                    continue
                except ConnectionResetError:
                    self._log(f"Client {addr} disconnected")
                    break
                except Exception as e:
                    self._log(f"Error handling client {addr}: {e}")
                    break
        except Exception as e:
            self._log(f"Error in client handler: {e}")
        finally:
            try:
                conn.close()
            except:
                pass
    
    def _cleanup(self):
        if self.server_socket:
            try:
                self.server_socket.close()
            except Exception as e:
                self._log(f"Error closing server: {e}")
            finally:
                self.server_socket = None
    
    def stop(self):
        self._log("Stopping server...")
        self.running = False
    
    def _log(self, message: str):
        if self.logger:
            self.logger.info(message)
        if self.log_signal:
            self.log_signal.emit(message)


class SocketServiceToggleTool:
    """
    服务端切换工具类
    
    提供启动/停止服务端的功能，可用于创建工具栏按钮。
    """
    
    def __init__(self, adapter, port: int = 7002):
        self.adapter = adapter
        self.port = port
        self.logger = adapter.get_logger()
        self.server_thread = None
        self.toolbutton = None
        
        try:
            self._create_toolbutton()
        except Exception:
            pass
    
    def _create_toolbutton(self):
        self.toolbutton = QToolButton()
        self.toolbutton.setCheckable(True)
        self.toolbutton.setToolTip(f"Toggle VS Code DCC Server (port {self.port})")
        
        try:
            current_dir = __import__('pathlib').Path(__file__).resolve().parent
            icon_path = current_dir.parent / "icon.png"
            if icon_path.exists():
                self.toolbutton.setIcon(QIcon(str(icon_path)))
        except Exception:
            pass
        
        self.toolbutton.clicked.connect(self._on_toggled)
        
        try:
            import importlib
            dcc_module = importlib.import_module(self.adapter.name)
            if hasattr(dcc_module, 'ui') and hasattr(dcc_module.ui, 'add_plugins_toolbar_widget'):
                dcc_module.ui.add_plugins_toolbar_widget(self.toolbutton)
        except Exception:
            pass
    
    def start(self):
        if self.server_thread is None:
            self.server_thread = SocketServerThread(port=self.port, adapter=self.adapter)
            self.server_thread.log_signal.connect(lambda msg: self.logger.info(msg))
            self.server_thread.start()
            
            if self.toolbutton:
                self.toolbutton.setChecked(True)
        else:
            self.logger.warn("Server is already running")
    
    def stop(self):
        if self.server_thread is not None:
            self.server_thread.stop()
            self.server_thread.quit()
            self.server_thread.wait(2000)
            self.server_thread = None
            self.logger.info("Server stopped")
            
            if self.toolbutton:
                self.toolbutton.setChecked(False)
        else:
            self.logger.warn("Server is not running")
    
    def _on_toggled(self):
        if self.toolbutton.isChecked():
            self.start()
        else:
            self.stop()
    
    def is_running(self) -> bool:
        return self.server_thread is not None and self.server_thread.isRunning()
